// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const text = ($input.first().json.output || '').replace(/\|\|/g, '\n');

// split on line breaks and sentence endings (. ! ? and Arabic ؟)
let parts = text
  .split(/\n+|(?<=[.!?؟])\s+/)
  .map(t => t.trim())
  .filter(Boolean);

// max 3 bubbles: merge the rest into the last one
if (parts.length > 3) {
  parts = [parts[0], parts[1], parts.slice(2).join(' ')];
}

return parts.map(t => ({ json: { text: t } }));

const now = DateTime.now().setZone('Europe/Amsterdam');
const hour = now.hour;
const isSunday = now.weekday === 7;

const out = [];

for (const item of $input.all()) {
  const u = item.json;
  if (String(u.onboarded).trim().toLowerCase() !== 'yes') continue;

  const morning = Number(u.morning_hour);
  const checkin = Number(u.checkin_hour);

  const seen = u.last_seen ? DateTime.fromISO(String(u.last_seen), { zone: 'Europe/Amsterdam' }) : null;
  const daysQuiet = seen ? Math.floor(now.diff(seen, 'days').days) : 0;

  const joined = u.joined ? DateTime.fromISO(String(u.joined), { zone: 'Europe/Amsterdam' }) : null;
  const daysHere = joined ? Math.floor(now.diff(joined, 'days').days) : 0;
  const thin = !u.name || !u.checkin_hour;

  let type = u.test_type ? String(u.test_type).trim() : null;
  if (!type) {
    if (thin && daysHere >= 2 && hour === 18) type = 'setup';
    else if (daysQuiet >= 3 && hour === checkin) type = 'quiet';
    else if (isSunday && hour === checkin) type = 'weekend';
    else if (hour === morning) type = 'morning';
    else if (hour === checkin) type = 'checkin';
  }

  if (type) out.push({ json: { ...u, type, daysQuiet, daysHere, today: now.toISODate() } });
}

return out;

parameters.text:
=You are Hio, a warm AI wellbeing companion. You are writing to {{ $json.name }} on Telegram.

Write in {{ $json.language }}. Tone: {{ $json.tone }}.
Write like a friend texting. 1 to 3 short sentences. No dashes, no lists, no headings, no emojis.
Do not start with "I understand" or "It sounds like". End with one short question.

Message type: {{ $json.type }}

If morning: say in one line what today looks like, then one small tip. If the day is busy, suggest a short break.
If checkin: ask how the day went and offer to journal together.
If weekend: ask how the week went, and suggest one low effort thing for the weekend. Use the weather and name one real place from the list below. If the list says none found, keep the suggestion general. Never invent a place name. If there are journal entries, mention one kind, specific pattern you noticed, and never judge. If there are none, do not mention journaling.

Context:
Today: {{ $json.today_events }}
Busy day: {{ $json.busy }}
Deadlines: {{ $json.deadlines }}
Supports with: {{ $json.struggles }}
City: {{ $json.city }}
Weekend weather: {{ $json.weather }}
Nearby places: {{ $json.places }}
Journal entries this week ({{ $json.journal_count }}): {{ $json.journal_week }}

If a deadline is close, mention it gently, without pressure.
Only use the context for the message type above. Ignore the rest.

