const base = $('Prepare').first().json;
const d = $input.first().json?.daily;

let weather = 'unknown';
if (d?.temperature_2m_max) {
  const max = Math.round(Math.max(...d.temperature_2m_max.slice(1, 8)));
  const rain = Math.max(...(d.precipitation_probability_max || [0]).slice(1, 8));
  weather = `up to ${max}°C, ${rain}% chance of rain`;
}

return [{ json: { ...base, weather, daily: d || null } }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const base = $('Add Weather').first().json;
const cutoff = DateTime.now().setZone('Europe/Amsterdam').minus({ days: 7 });

const entries = $input.all()
  .map(i => i.json)
  .filter(e => e.date && DateTime.fromFormat(String(e.date), 'yyyy-MM-dd HH:mm', { zone: 'Europe/Amsterdam' }) >= cutoff)
  .map(e => `${e.date}: ${e.answer}`);

return [{ json: {
  ...base,
  journal_week: entries.join(' | ') || 'no entries this week',
  journal_count: entries.length,
}}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const base = $('Week Journal').first().json;
const els = $input.first().json?.elements || [];

const pick = (n) => els
  .filter(e => e.tags?.name && (e.tags.amenity === n || e.tags.leisure === n || e.tags.tourism === n))
  .slice(0, 3)
  .map(e => e.tags.name);

const places = [
  ...pick('park').map(n => `${n} (park)`),
  ...pick('cafe').map(n => `${n} (cafe)`),
  ...pick('museum').map(n => `${n} (museum)`),
];

return [{ json: { ...base, places: places.join(', ') || 'none found' } }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const user = $('Who To Message').first().json;
const tz = 'Europe/Amsterdam';
const now = DateTime.now().setZone(tz);
const today = now.toISODate();

const events = $input.all().map(i => i.json).filter(e => e.summary);

const fmt = e => {
  const s = e.start?.dateTime ? DateTime.fromISO(e.start.dateTime).setZone(tz).toFormat('HH:mm') : 'all day';
  return `${s} ${e.summary.trim()}`;
};

const todayEvents = events
  .filter(e => (e.start?.dateTime || e.start?.date || '').startsWith(today))
  .map(fmt);

const deadlines = events
  .filter(e => /^DEADLINE:/i.test(e.summary.trim()))
  .map(e => {
    const d = e.start?.dateTime || e.start?.date;
    const days = Math.round(DateTime.fromISO(d).setZone(tz).startOf('day').diff(now.startOf('day'), 'days').days);
    return `${e.summary.trim()} (in ${days} day(s))`;
  });

return [{ json: {
  ...user,
  today_events: todayEvents.join(', ') || 'nothing scheduled',
  busy: todayEvents.length >= 4,
  deadlines: deadlines.join(', ') || 'none',
}}];

const b = $('Add Places').first().json;
const tz = 'Europe/Amsterdam';
const now = DateTime.now().setZone(tz);
const start = now.minus({ days: 6 }).startOf('day');
const who = b.name || b['name '] || 'you';

// habits, last 7 days
const logs = $input.all().map(i => i.json).filter(r => r.habit);
const week = logs.filter(r => DateTime.fromISO(String(r.date), { zone: tz }) >= start);
const pastDays = [...Array(7)].map((_, i) => start.plus({ days: i }));
const habits = [...new Set(week.map(r => r.habit))];
const grid = habits.map(h => {
  const cells = pastDays.map(d => {
    const hit = week.some(r => r.habit === h && String(r.date) === d.toISODate());
    return `<td class="${hit ? 'on' : 'off'}">${hit ? '✓' : ''}</td>`;
  }).join('');
  return `<tr><th>${h}</th>${cells}</tr>`;
}).join('');

// week ahead, monday to sunday
const mon = now.plus({ days: 1 }).startOf('day');
const ahead = [...Array(7)].map((_, i) => mon.plus({ days: i }));

const events = $('Read Calendar').all().map(i => i.json).filter(e => e.summary);
const wx = b.daily || {};
const codes = { 0:'Clear', 1:'Mostly clear', 2:'Partly cloudy', 3:'Cloudy', 45:'Fog', 48:'Fog', 51:'Drizzle', 53:'Drizzle', 55:'Drizzle', 61:'Rain', 63:'Rain', 65:'Heavy rain', 71:'Snow', 73:'Snow', 75:'Snow', 80:'Showers', 81:'Showers', 82:'Showers', 95:'Storm', 96:'Storm', 99:'Storm' };

const rows = ahead.map(d => {
  const iso = d.toISODate();
  const idx = (wx.time || []).indexOf(iso);
  const sky = idx > -1 ? (codes[wx.weather_code[idx]] || '') : '';
  const temp = idx > -1 ? `${Math.round(wx.temperature_2m_min[idx])} to ${Math.round(wx.temperature_2m_max[idx])}°` : '';
  const rain = idx > -1 && wx.precipitation_probability_max[idx] >= 40 ? ` · ${wx.precipitation_probability_max[idx]}% rain` : '';

  const day = events.filter(e => (e.start?.dateTime || e.start?.date || '').startsWith(iso));
  const dl = day.filter(e => /^DEADLINE:/i.test(e.summary.trim()));
  const ev = day.filter(e => !/^DEADLINE:/i.test(e.summary.trim()));

  const items = [
    ...dl.map(e => `<span class="dl">${e.summary.replace(/^DEADLINE:\s*/i, '')}</span>`),
    ...ev.map(e => `<span class="ev">${e.start?.dateTime ? DateTime.fromISO(e.start.dateTime).setZone(tz).toFormat('HH:mm') + ' ' : ''}${e.summary.trim()}</span>`),
  ].join('');

  const heavy = ev.length >= 4;
  return `<tr class="${heavy ? 'heavy' : ''}">
    <th><div class="dname">${d.toFormat('ccc')}</div><div class="dnum">${d.toFormat('d LLL')}</div></th>
    <td class="wx">${sky}<div class="t">${temp}${rain}</div></td>
    <td class="ev-cell">${items || '<span class="free">free</span>'}</td></tr>`;
}).join('');

const journal = (b.journal_week || '').split(' | ').filter(Boolean)
  .map(e => `<div class="entry">${e}</div>`).join('');
const journalEmpty = !journal;
const empty = habits.length === 0;

const html = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Your week with Hio</title><style>
*{box-sizing:border-box;margin:0;padding:0}
body{font:16px/1.65 -apple-system,system-ui,sans-serif;background:#f3efe6;color:#1d2b2a;padding:20px}
.wrap{max-width:680px;margin:0 auto}
.hero{background:#1d2b2a;color:#f3efe6;border-radius:28px;padding:40px 32px 36px;position:relative;overflow:hidden;margin-bottom:14px}
.hero h1{font-size:32px;font-weight:600;line-height:1.2;position:relative;z-index:1}
.hero .dates{color:#9fb0aa;margin-top:8px;font-size:15px;position:relative;z-index:1}
.hero .line{color:#d9975b;font-size:13px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;position:relative;z-index:1}
.blob{position:absolute;border-radius:50%}
.b1{width:180px;height:180px;background:#4f7d6a;opacity:.3;right:-40px;bottom:-70px}
.b2{width:90px;height:90px;background:#d9975b;opacity:.22;right:90px;top:-20px}
.card{background:#fbf9f4;border-radius:24px;padding:26px 28px 28px;margin-bottom:14px;border:1px solid #e9e2d4}
.card h2{font-size:14px;letter-spacing:1.5px;text-transform:uppercase;color:#4f7d6a;margin-bottom:18px;font-weight:600}
table{width:100%;border-collapse:separate;border-spacing:5px;margin-left:-5px}
.habits th{text-align:left;font-weight:500;font-size:15px;padding-right:10px;white-space:nowrap}
.habits td{width:34px;height:34px;text-align:center;border-radius:11px;font-size:15px;font-weight:700}
.habits td.on{background:#4f7d6a;color:#fff}
.habits td.off{background:#ece6d9}
.dayrow td{background:none!important;font-size:11px;color:#9aa49f;font-weight:600;height:22px}
.week th{text-align:left;width:74px;vertical-align:top;padding-top:10px}
.dname{font-size:15px;font-weight:600}
.dnum{font-size:12px;color:#9aa49f;font-weight:500}
.week td{vertical-align:top;padding:10px 12px;background:#f3efe6;border-radius:12px}
.week tr.heavy td{background:#f7e9d8}
.wx{width:120px;font-size:13.5px;color:#3f6b5a}
.wx .t{color:#9aa49f;font-size:12.5px;margin-top:2px}
.ev-cell span{display:block;font-size:14px;margin-bottom:3px}
.ev-cell .dl{color:#c07a2e;font-weight:600}
.free{color:#b3bcb7;font-style:italic}
.entry{background:#f3efe6;border-left:3px solid #d9975b;border-radius:10px;padding:14px 16px;margin-bottom:8px;font-size:15px}
.empty{color:#8b958f;font-size:15px}
.save{background:#1d2b2a;color:#a9b6b1;border-radius:24px;padding:24px 28px;font-size:13.5px;line-height:1.75}
.save b{color:#f3efe6;display:block;margin-bottom:10px;font-size:13px;letter-spacing:1.2px;text-transform:uppercase}
.save span{color:#d9975b;font-weight:600}
.foot{text-align:center;color:#9aa49f;font-size:12.5px;margin:20px 0 6px}
</style></head><body><div class="wrap">

<div class="hero"><div class="blob b1"></div><div class="blob b2"></div>
<div class="line">Week in review</div>
<h1>Your week, ${who}</h1>
<div class="dates">${start.toFormat('d LLLL')} to ${now.toFormat('d LLLL yyyy')}</div></div>

<div class="card"><h2>Habits</h2>
${empty ? '<div class="empty">Nothing logged yet. Tell Hio what you would like to keep up, and this fills itself in.</div>'
 : `<table class="habits"><tr class="dayrow"><th></th>${pastDays.map(d => `<td>${d.toFormat('ccc').toUpperCase()}</td>`).join('')}</tr>${grid}</table>`}</div>

<div class="card"><h2>What you wrote</h2>
${journalEmpty ? '<div class="empty">A quiet week on paper. That is allowed.</div>' : journal}</div>

<div class="card"><h2>The week ahead in ${b.city}</h2>
<table class="week">${rows}</table></div>

<div class="save"><b>Keep this</b>
<span>iPhone</span> Share icon in Safari, then Print, pinch out on the preview, share again, Save to Files.<br>
<span>Android</span> Chrome menu, then Share, then Print, then Save as PDF.</div>

<div class="foot">Made by Hio. Not a medical record, just your week.</div>
</div></body></html>`;

return [{ json: { ...b, filename: `week-${now.toISODate()}.html` }, binary: {
  data: await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), `week-${now.toISODate()}.html`, 'text/html')
}}];
